CREATE TABLE IF NOT EXISTS "application_settings_master_t" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "application_settings_master_t_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"project_name" varchar(100) DEFAULT 'Stock' NOT NULL,
	"tab_title" varchar(100) DEFAULT 'Stock Management' NOT NULL,
	"tagline" varchar(150) DEFAULT 'Inventory System',
	"footer_text" varchar(255) DEFAULT '© {year} GPTCN Admin · All rights reserved.',
	"footer_credit" varchar(255) DEFAULT 'Designed by Department of Computer Engineering',
	"letterhead" text,
	"accent_color" varchar(20) DEFAULT '#818cf8',
	"accent_fg_color" varchar(20) DEFAULT '#c7d2fe',
	"sidebar_bg" varchar(20),
	"sidebar_text" varchar(20),
	"updated_by" integer,
	"created_at" timestamp DEFAULT now(),
	"updated_at" timestamp DEFAULT now()
);
